/**
 * The player's settings and furniture on this computer: the Settings
 * dialog's switches (spec §15), each slot's place and style (§7.2, §7.4:
 * "per slot, for every video"), the volume, which hints were used, and the
 * one-time moments. It is this device's furniture, not the learner's data,
 * so it is not synced; it lives in `platform.prefs` like the sidebar's
 * state, under one key, and every read is checked: anything unreadable
 * falls back to the default for that one field.
 */
import { platform } from '@/lib/platform/index.js';
import { defaultLayout, MAX_SCALE, MAX_WIDTH, MIN_SCALE, MIN_WIDTH, type SlotLayout } from './layout.js';
import type { SlotNumber } from './slots.js';

export const PREFS_KEY = 'lexpad.player';

export type FontChoice = 'auto' | 'sans' | 'vazirmatn' | 'naskh' | 'atkinson' | 'serif' | 'system';
export type Edge = 'none' | 'outline' | 'shadow' | 'box';
/** The four colours the panel offers, or a custom "#rrggbb". */
export type Colour = 'white' | 'yellow' | 'sky' | 'mint' | `#${string}`;

export interface SlotStyle {
  font: FontChoice;
  colour: Colour;
  edge: Edge;
  /** The Box edge's opacity, 0–1. */
  boxOpacity: number;
  /** The text's opacity, 0.5–1. */
  opacity: number;
}

export function defaultStyle(slot: SlotNumber): SlotStyle {
  return {
    font: 'auto',
    colour: slot === 1 ? 'white' : slot === 2 ? 'yellow' : 'sky',
    edge: 'outline',
    boxOpacity: 0.62,
    opacity: 1,
  };
}

export interface PlayerSettings {
  resume: boolean;
  nextEpisode: boolean;
  /** Seconds before the next episode plays: 5, 10 or 15. */
  nextDelay: 5 | 10 | 15;
  /** The ← / → step in seconds. */
  skip: 5 | 10;
  resumeAfterWord: boolean;
  rememberSpeed: boolean;
  pauseMinimised: boolean;
  theme: 'dark' | 'system';
  markNotebook: boolean;
  pauseOnPoint: boolean;
  askEachFile: boolean;
  fixText: boolean;
  myStyleForAss: boolean;
  preferredAudio: 'original' | 'learning' | 'own';
  boost: boolean;
  evenOut: boolean;
  keepVoice: boolean;
  previews: boolean;
  recent: boolean;
  singleKeys: boolean;
  readAloud: boolean;
}

export const DEFAULT_SETTINGS: PlayerSettings = {
  resume: true,
  nextEpisode: true,
  nextDelay: 10,
  skip: 5,
  resumeAfterWord: true,
  rememberSpeed: false,
  pauseMinimised: false,
  theme: 'dark',
  markNotebook: false,
  pauseOnPoint: true,
  askEachFile: true,
  fixText: true,
  myStyleForAss: true,
  preferredAudio: 'original',
  boost: true,
  evenOut: false,
  keepVoice: true,
  previews: true,
  recent: true,
  singleKeys: true,
  readAloud: false,
};

/** The three hints under the drop zone, and the first-point hint (§4.2, §7.4). */
export interface Hints {
  drop: boolean;
  move: boolean;
  word: boolean;
  point: boolean;
}

export interface PlayerPrefs {
  volume: number;
  muted: boolean;
  settings: PlayerSettings;
  layouts: Record<SlotNumber, SlotLayout>;
  styles: Record<SlotNumber, SlotStyle>;
  hints: Hints;
  /** The local day the end summary last showed its Pro line (at most once a day, §12). */
  nudgeDay?: string;
  /** The local day sign-in was last asked at a save (at most once a day, §10). */
  signInAskDay?: string;
  /** The default-player offer (§24.6): earned after a 3-minute video, shown once. */
  offer: { earned: boolean; done: boolean };
  /** The first-open soft sign-in was answered (§4.1): shown once per install. */
  firstOpenDone: boolean;
  /** Speed per video, only when "Remember speed per video" is on. */
  speeds: Record<string, number>;
  /** What was hidden, per video (§7.5). */
  hidden: Record<string, { master: boolean; slots: [boolean, boolean, boolean] }>;
}

/** How many videos keep their hidden state and speed; the oldest go first. */
export const MAX_REMEMBERED_VIDEOS = 200;

export function defaultPrefs(): PlayerPrefs {
  return {
    volume: 1,
    muted: false,
    settings: { ...DEFAULT_SETTINGS },
    layouts: { 1: defaultLayout(1), 2: defaultLayout(2), 3: defaultLayout(3) },
    styles: { 1: defaultStyle(1), 2: defaultStyle(2), 3: defaultStyle(3) },
    hints: { drop: false, move: false, word: false, point: false },
    offer: { earned: false, done: false },
    firstOpenDone: false,
    speeds: {},
    hidden: {},
  };
}

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function num(v: unknown, lo: number, hi: number, fallback: number): number {
  return typeof v === 'number' && Number.isFinite(v) && v >= lo && v <= hi ? v : fallback;
}

function bool(v: unknown, fallback: boolean): boolean {
  return typeof v === 'boolean' ? v : fallback;
}

function readLayout(v: unknown, slot: SlotNumber): SlotLayout {
  const d = defaultLayout(slot);
  if (!isObj(v)) return d;
  const mode = v.mode === 'bottom' || v.mode === 'top' || v.mode === 'custom' ? v.mode : d.mode;
  const anchor = v.anchor === 'bottom' || v.anchor === 'top' ? v.anchor : d.anchor;
  return {
    mode,
    anchor,
    x: num(v.x, 0, 1, d.x),
    y: num(v.y, 0, 1, d.y),
    width: num(v.width, MIN_WIDTH, MAX_WIDTH, d.width),
    scale: num(v.scale, MIN_SCALE, MAX_SCALE, d.scale),
  };
}

const FONTS: readonly FontChoice[] = ['auto', 'sans', 'vazirmatn', 'naskh', 'atkinson', 'serif', 'system'];
const EDGES: readonly Edge[] = ['none', 'outline', 'shadow', 'box'];

function readColour(v: unknown, fallback: Colour): Colour {
  if (v === 'white' || v === 'yellow' || v === 'sky' || v === 'mint') return v;
  if (typeof v === 'string' && /^#[0-9a-f]{6}$/i.test(v)) return v as Colour;
  return fallback;
}

function readStyle(v: unknown, slot: SlotNumber): SlotStyle {
  const d = defaultStyle(slot);
  if (!isObj(v)) return d;
  return {
    font: FONTS.includes(v.font as FontChoice) ? (v.font as FontChoice) : d.font,
    colour: readColour(v.colour, d.colour),
    edge: EDGES.includes(v.edge as Edge) ? (v.edge as Edge) : d.edge,
    boxOpacity: num(v.boxOpacity, 0, 1, d.boxOpacity),
    opacity: num(v.opacity, 0.5, 1, d.opacity),
  };
}

function readSettings(v: unknown): PlayerSettings {
  const d = DEFAULT_SETTINGS;
  if (!isObj(v)) return { ...d };
  const out = { ...d };
  for (const key of Object.keys(d) as (keyof PlayerSettings)[]) {
    const dv = d[key];
    const value = v[key];
    if (typeof dv === 'boolean') (out as Record<string, unknown>)[key] = bool(value, dv);
  }
  out.nextDelay = value3(v.nextDelay, [5, 10, 15], d.nextDelay);
  out.skip = value3(v.skip, [5, 10], d.skip);
  out.theme = v.theme === 'system' ? 'system' : 'dark';
  out.preferredAudio =
    v.preferredAudio === 'learning' || v.preferredAudio === 'own' ? v.preferredAudio : 'original';
  return out;
}

function value3<T extends number>(v: unknown, allowed: readonly T[], fallback: T): T {
  return allowed.includes(v as T) ? (v as T) : fallback;
}

function readRecord<T>(v: unknown, read: (x: unknown) => T | undefined): Record<string, T> {
  if (!isObj(v)) return {};
  const out: Record<string, T> = {};
  for (const [k, x] of Object.entries(v).slice(-MAX_REMEMBERED_VIDEOS)) {
    const r = read(x);
    if (r !== undefined) out[k] = r;
  }
  return out;
}

export function parsePrefs(raw: string | null): PlayerPrefs {
  const d = defaultPrefs();
  if (raw === null) return d;
  let v: unknown;
  try {
    v = JSON.parse(raw);
  } catch {
    return d;
  }
  if (!isObj(v)) return d;
  const hints = isObj(v.hints) ? v.hints : {};
  const offer = isObj(v.offer) ? v.offer : {};
  const layouts = isObj(v.layouts) ? v.layouts : {};
  const styles = isObj(v.styles) ? v.styles : {};
  return {
    volume: num(v.volume, 0, 2, d.volume),
    muted: bool(v.muted, d.muted),
    settings: readSettings(v.settings),
    layouts: {
      1: readLayout(layouts['1'], 1),
      2: readLayout(layouts['2'], 2),
      3: readLayout(layouts['3'], 3),
    },
    styles: { 1: readStyle(styles['1'], 1), 2: readStyle(styles['2'], 2), 3: readStyle(styles['3'], 3) },
    hints: {
      drop: bool(hints.drop, false),
      move: bool(hints.move, false),
      word: bool(hints.word, false),
      point: bool(hints.point, false),
    },
    ...(typeof v.nudgeDay === 'string' ? { nudgeDay: v.nudgeDay } : {}),
    ...(typeof v.signInAskDay === 'string' ? { signInAskDay: v.signInAskDay } : {}),
    offer: { earned: bool(offer.earned, false), done: bool(offer.done, false) },
    firstOpenDone: bool(v.firstOpenDone, false),
    speeds: readRecord(v.speeds, (x) => (typeof x === 'number' && x >= 0.25 && x <= 4 ? x : undefined)),
    hidden: readRecord(v.hidden, (x) => {
      if (!isObj(x) || !Array.isArray(x.slots) || x.slots.length !== 3) return undefined;
      const [a, b, c] = x.slots as unknown[];
      return { master: bool(x.master, true), slots: [bool(a, true), bool(b, true), bool(c, true)] };
    }),
  };
}

export function loadPrefs(): PlayerPrefs {
  return parsePrefs(platform.prefs.get(PREFS_KEY));
}

export function savePrefs(prefs: PlayerPrefs): void {
  platform.prefs.set(PREFS_KEY, JSON.stringify(prefs));
}

/** The local calendar day, "2026-10-25", for the once-a-day rules. */
export function localDay(now: Date): string {
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  const d = String(now.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

/** A video's key for what is remembered about it on this computer: its name and size. */
export function videoKey(name: string, size: number): string {
  return `${name}|${size}`;
}
