/**
 * Where subtitles sit and how big they are (spec §7.1, §7.4, §4.4). Pure
 * geometry, so it is tested plainly and the overlay only applies it.
 *
 * Positions are fractions of the player area (the window minus the side
 * panel), not of the picture, so a line can sit in a black bar. A box is
 * anchored to the bottom or the top edge; `y` is the distance of that edge
 * of the box from that edge of the area.
 */
import type { SlotNumber } from './slots.js';

export interface Size {
  w: number;
  h: number;
}

export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export type Anchor = 'bottom' | 'top';

export interface SlotLayout {
  /** Bottom or Top as the panel's Place control says, or Custom once dragged. */
  mode: 'bottom' | 'top' | 'custom';
  anchor: Anchor;
  /** The box's centre, a fraction of the area's width. */
  x: number;
  /** The anchored edge's distance from that edge of the area, a fraction of its height. */
  y: number;
  /** The longest a line may run, a fraction of the area's width (20–100%). */
  width: number;
  /** The text's size against the slot's default (50–200%). */
  scale: number;
}

/**
 * The default places, as the approved mock-ups draw them (1440×900 and
 * 1280×800): Subtitle 1's bottom edge at 9% of the area, Subtitle 2's top
 * edge at 6%, Subtitle 3 stacked above Subtitle 1. Lines run to 80% of the
 * area's width at most.
 */
export const DEFAULT_BOTTOM_Y = 0.09;
export const DEFAULT_TOP_Y = 0.06;
export const DEFAULT_WIDTH = 0.8;
/** Subtitle 3 sits this far above Subtitle 1 until it is dragged (§7.1). */
export const STACK_GAP_PX = 8;

export function defaultLayout(slot: SlotNumber): SlotLayout {
  if (slot === 2)
    return { mode: 'top', anchor: 'top', x: 0.5, y: DEFAULT_TOP_Y, width: DEFAULT_WIDTH, scale: 1 };
  return { mode: 'bottom', anchor: 'bottom', x: 0.5, y: DEFAULT_BOTTOM_Y, width: DEFAULT_WIDTH, scale: 1 };
}

/** Subtitle 1's size, a fraction of the 16:9 picture's height (36 px at 1440×900). */
export const BASE_SIZE = 0.044;
/** Each slot's size against Subtitle 1's (§7.1). */
export const SLOT_SIZE: Record<SlotNumber, number> = { 1: 1, 2: 0.86, 3: 0.8 };
/** On-screen bounds for any subtitle, and the small window's floor (§7.2, §6.9). */
export const MIN_FONT_PX = 16;
export const MAX_FONT_PX = 96;
export const MIN_SCALE = 0.5;
export const MAX_SCALE = 2;
export const MIN_WIDTH = 0.2;
export const MAX_WIDTH = 1;

/** The 16:9 picture's height in an area, the yardstick every size is measured with. */
export function pictureHeight(area: Size): number {
  return Math.min(area.h, (area.w * 9) / 16);
}

/** A subtitle's font size in pixels. */
export function fontPx(area: Size, slot: SlotNumber, scale: number): number {
  const px = pictureHeight(area) * BASE_SIZE * SLOT_SIZE[slot] * clamp(scale, MIN_SCALE, MAX_SCALE);
  return clamp(px, MIN_FONT_PX, MAX_FONT_PX);
}

/** Where the picture of a video with this aspect ratio lands in the area. */
export function pictureRect(area: Size, aspect: number): Rect {
  const a = aspect > 0 && Number.isFinite(aspect) ? aspect : 16 / 9;
  const w = Math.min(area.w, area.h * a);
  const h = w / a;
  return { x: (area.w - w) / 2, y: (area.h - h) / 2, w, h };
}

export function clamp(v: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, v));
}

/* ------------------------------------------------------------ lifting */

/** The control bar's zone and the top bar (§1, §4.4). */
export const CONTROL_ZONE_PX = 112;
export const TOP_BAR_PX = 52;
/**
 * How far a subtitle rises while the bars show, and the line it rises to
 * clear: the mock-ups draw Subtitle 1 at "9% + 92 px" and Subtitle 2 at
 * "6% + 40 px" with the chrome up, at every window size.
 */
export const LIFT_BOTTOM_MAX = 92;
export const LIFT_BOTTOM_CLEAR = CONTROL_ZONE_PX + LIFT_BOTTOM_MAX;
export const LIFT_TOP_MAX = 40;
export const LIFT_TOP_CLEAR = TOP_BAR_PX + 48;

/**
 * How far a box moves away from its edge while the bars show: just enough
 * to clear them, never more than the design's lift, and nothing for a box
 * already clear of them.
 */
export function liftPx(anchor: Anchor, edgePx: number): number {
  if (anchor === 'bottom') return Math.min(LIFT_BOTTOM_MAX, Math.max(0, LIFT_BOTTOM_CLEAR - edgePx));
  return Math.min(LIFT_TOP_MAX, Math.max(0, LIFT_TOP_CLEAR - edgePx));
}

/**
 * A slot's lift as a signed offset (negative is up), from its place alone:
 * the part of its position the bars add, which the overlay animates apart
 * from the line so a new line never moves (§7.1).
 */
export function liftFor(area: Size, layout: SlotLayout, chrome: boolean): number {
  if (!chrome) return 0;
  const edge = layout.y * area.h;
  return layout.anchor === 'bottom' ? -liftPx('bottom', edge) : liftPx('top', edge);
}

/* ------------------------------------------------------------ boxes */

export interface PlacedBox {
  slot: SlotNumber;
  /** The box in the area, after stacking and lifting. */
  rect: Rect;
  anchor: Anchor;
  /**
   * The part of `rect.y` that is the bars' lift (negative is up, 0 with the
   * bars hidden). It depends only on the slot's place, never on its text, so
   * the overlay can animate it alone: the box rises when the bars appear and
   * never moves when its line changes.
   */
  lift: number;
}

export interface BoxInput {
  slot: SlotNumber;
  layout: SlotLayout;
  /** The box's measured size (its text as laid out now). */
  size: Size;
  /** Subtitle 3 before it is dragged: stacked above Subtitle 1. */
  stacked: boolean;
}

/**
 * Lays the boxes out in slot order: each at its place, Subtitle 3 above
 * Subtitle 1 when stacked, lifted clear of the bars when they show (and of a
 * notice in the top-left corner), and pushed away from a box earlier in the
 * order it would overlap, so tracks never cover each other.
 */
export function placeBoxes(
  area: Size,
  boxes: readonly BoxInput[],
  opts: { chrome: boolean; notice?: Rect | null },
): PlacedBox[] {
  const out: PlacedBox[] = [];
  const sorted = [...boxes].sort((a, b) => a.slot - b.slot);
  for (const b of sorted) {
    const { layout, size } = b;
    const cx = layout.x * area.w;
    let x = cx - size.w / 2;
    x = clamp(x, 0, Math.max(0, area.w - size.w));
    let y: number;
    let lift: number;
    let anchor = layout.anchor;
    const first = out.find((p) => p.slot === 1);
    if (b.stacked && first !== undefined) {
      anchor = 'bottom';
      y = first.rect.y - STACK_GAP_PX - size.h;
      lift = first.lift;
    } else {
      const edge = layout.y * area.h;
      lift = liftFor(area, layout, opts.chrome);
      y = anchor === 'bottom' ? area.h - edge - size.h + lift : edge + lift;
    }
    let rect: Rect = { x, y, w: size.w, h: size.h };
    // A notice never covers a subtitle: a top track steps down below it.
    const notice = opts.notice;
    if (notice && anchor === 'top' && overlaps(rect, notice)) rect = { ...rect, y: notice.y + notice.h + 8 };
    for (const p of out) {
      if (!overlaps(rect, p.rect)) continue;
      rect =
        anchor === 'bottom'
          ? { ...rect, y: p.rect.y - STACK_GAP_PX - rect.h }
          : { ...rect, y: p.rect.y + p.rect.h + STACK_GAP_PX };
    }
    rect = { ...rect, y: clamp(rect.y, 0, Math.max(0, area.h - rect.h)) };
    out.push({ slot: b.slot, rect, anchor, lift });
  }
  return out;
}

export function overlaps(a: Rect, b: Rect): boolean {
  return a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
}

/* ------------------------------------------------------------ dragging */

/** Guides snap within this many pixels (§7.4). */
export const SNAP_PX = 8;
/** The safe area shown while dragging: 5% in from every edge. */
export const SAFE = 0.05;

export type GuideKind =
  'centre' | 'safeTop' | 'safeBottom' | 'pictureTop' | 'pictureBottom' | 'bar' | 'track';

export interface Guide {
  kind: GuideKind;
  axis: 'v' | 'h';
  /** Pixels from the area's left (v) or top (h). */
  at: number;
}

/** Every line a dragged box may snap to. */
export function guidesFor(area: Size, picture: Rect, others: readonly Rect[]): Guide[] {
  const g: Guide[] = [
    { kind: 'centre', axis: 'v', at: area.w / 2 },
    { kind: 'safeTop', axis: 'h', at: area.h * SAFE },
    { kind: 'safeBottom', axis: 'h', at: area.h * (1 - SAFE) },
  ];
  if (picture.y > 1) {
    g.push({ kind: 'pictureTop', axis: 'h', at: picture.y });
    g.push({ kind: 'pictureBottom', axis: 'h', at: picture.y + picture.h });
    g.push({ kind: 'bar', axis: 'h', at: picture.y / 2 });
    g.push({ kind: 'bar', axis: 'h', at: picture.y + picture.h + (area.h - picture.y - picture.h) / 2 });
  }
  for (const r of others) {
    g.push({ kind: 'track', axis: 'h', at: r.y });
    g.push({ kind: 'track', axis: 'h', at: r.y + r.h });
    g.push({ kind: 'track', axis: 'h', at: r.y + r.h / 2 });
  }
  return g;
}

export interface SnapResult {
  rect: Rect;
  guides: Guide[];
}

/**
 * Snaps a box being dragged: its centre to a vertical guide, and its top,
 * bottom or middle to a horizontal one, each within `SNAP_PX`. `free`
 * (⌘ or Ctrl held) snaps nothing.
 */
export function snap(rect: Rect, guides: readonly Guide[], free: boolean): SnapResult {
  if (free) return { rect, guides: [] };
  let best: { d: number; g: Guide; dx: number } | undefined;
  const cx = rect.x + rect.w / 2;
  for (const g of guides) {
    if (g.axis !== 'v') continue;
    const d = Math.abs(cx - g.at);
    if (d <= SNAP_PX && (best === undefined || d < best.d)) best = { d, g, dx: g.at - cx };
  }
  let bestH: { d: number; g: Guide; dy: number } | undefined;
  const edges = [rect.y, rect.y + rect.h, rect.y + rect.h / 2];
  for (const g of guides) {
    if (g.axis !== 'h') continue;
    for (const e of edges) {
      const d = Math.abs(e - g.at);
      if (d <= SNAP_PX && (bestH === undefined || d < bestH.d)) bestH = { d, g, dy: g.at - e };
    }
  }
  const out: Guide[] = [];
  let r = rect;
  if (best) {
    r = { ...r, x: r.x + best.dx };
    out.push(best.g);
  }
  if (bestH) {
    r = { ...r, y: r.y + bestH.dy };
    out.push(bestH.g);
  }
  return { rect: r, guides: out };
}

/** A dragged box's place, kept as fractions: anchored to whichever edge its centre is nearer. */
export function layoutFromRect(area: Size, rect: Rect, prev: SlotLayout): SlotLayout {
  const anchor: Anchor = rect.y + rect.h / 2 < area.h / 2 ? 'top' : 'bottom';
  const y = anchor === 'top' ? rect.y / area.h : (area.h - rect.y - rect.h) / area.h;
  return {
    ...prev,
    mode: 'custom',
    anchor,
    x: clamp((rect.x + rect.w / 2) / area.w, 0, 1),
    y: clamp(y, 0, 1),
  };
}

/** The readout while dragging: "x 50% · y 5%". */
export function readout(layout: SlotLayout): { x: number; y: number } {
  return { x: Math.round(layout.x * 100), y: Math.round(layout.y * 100) };
}

/* ------------------------------------------------------------ keyboard */

/** Arrow keys move a focused grip 1% of the area, 5% with Shift (§7.4). */
export const KEY_STEP = 0.01;
export const KEY_STEP_BIG = 0.05;
/** + and − change the size by this much. */
export const KEY_SCALE_STEP = 0.1;

export function moveBy(layout: SlotLayout, dx: number, dy: number): SlotLayout {
  // `dy` is screen-down; a bottom-anchored box's `y` grows upwards.
  const y = layout.anchor === 'bottom' ? layout.y - dy : layout.y + dy;
  return { ...layout, mode: 'custom', x: clamp(layout.x + dx, 0, 1), y: clamp(y, 0, 0.95) };
}

export function scaleBy(layout: SlotLayout, step: number): SlotLayout {
  return { ...layout, scale: round2(clamp(layout.scale + step, MIN_SCALE, MAX_SCALE)) };
}

export function widthTo(layout: SlotLayout, width: number): SlotLayout {
  return { ...layout, width: round2(clamp(width, MIN_WIDTH, MAX_WIDTH)) };
}

function round2(v: number): number {
  return Math.round(v * 100) / 100;
}

/** The Place control: Bottom or Top go back to that edge's default; Custom keeps the drag. */
export function placeTo(layout: SlotLayout, place: 'bottom' | 'top'): SlotLayout {
  return place === 'bottom'
    ? { ...layout, mode: 'bottom', anchor: 'bottom', x: 0.5, y: DEFAULT_BOTTOM_Y }
    : { ...layout, mode: 'top', anchor: 'top', x: 0.5, y: DEFAULT_TOP_Y };
}
